const allowed = new Set(['spawn_candidate','start_training','submit_evaluation','request_repair','quarantine_candidate','request_promotion_review']);
const body = $json.body && typeof $json.body === 'object' ? $json.body : $json;
const action = String(body.action || '');
if (!allowed.has(action)) {
  return [{ json: { accepted: false, status: 'BLOCKED', reason: 'unmapped nursery action', action } }];
}
const requestedAutonomy = String(body.autonomy_level || 'A3');
if (!/^A[0-3]$/.test(requestedAutonomy)) {
  return [{ json: { accepted: false, status: 'BLOCKED', reason: 'nursery autonomy exceeds A3 ceiling', action, requested_autonomy: requestedAutonomy } }];
}
return [{ json: { accepted: true, status: 'ACCEPTED_FOR_FACTORY_GATE', action, candidate_ref: body.candidate_ref || null, autonomy_level: requestedAutonomy, payload: body.payload && typeof body.payload === 'object' ? body.payload : {}, authority: { root_of_trust_mutation: false, self_promotion: false, production_write_authority: false } } }];
